<?php

namespace App\Support;

use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Schema;
use RuntimeException;

/**
 * Fail-closed adoption of a historical emission_trends table.
 *
 * A missing migration ledger row must never cause existing research data to
 * be dropped or an incompatible schema to be silently marked as migrated.
 */
final class ExistingEmissionTrendsSchema
{
    private const TABLE = 'emission_trends';

    // Types are those generated by the original migration on MySQL 8.
    // Nullable is true for measurement fields and Laravel timestamps.
    private const TYPES = [
        'id' => 'bigint unsigned',
        'year' => 'smallint unsigned',
        'basinwide_ch4_emiss_mg_hr' => 'decimal(12,5)',
        'oil_million_bbls' => 'decimal(12,6)',
        'gas_million_bbleq' => 'decimal(12,6)',
        'energy_million_bbleq' => 'decimal(12,6)',
        'oil_gas_ratio' => 'decimal(12,6)',
        'winterozone_exceed_num' => 'int unsigned',
        'producing_wells' => 'int unsigned',
        'newwells' => 'int unsigned',
        'prodfromhighwells_thousbbleq_mnth' => 'decimal(14,6)',
        'prodfromlowwells_thousbbleq_mnth' => 'decimal(14,6)',
        'prodfromoilwells_thousbbleq_mnth' => 'decimal(14,6)',
        'prodfromgaswells_thousbbleq_mnth' => 'decimal(14,6)',
        'pcnt_prodfromhighwells' => 'decimal(12,6)',
        'gaswells' => 'int unsigned',
        'oilwells' => 'int unsigned',
        'new_gaswells' => 'int unsigned',
        'new_oilwells' => 'int unsigned',
        'highprodwells' => 'int unsigned',
        'lowprodwells' => 'int unsigned',
        'emissinens_totenergy' => 'decimal(12,6)',
        'emissinens_gas' => 'decimal(12,6)',
        'emisco2eq20_millnmg' => 'decimal(14,6)',
        'utahgasprice_dollpermcf' => 'decimal(12,6)',
        'utahcrudeprice_dollperbbl' => 'decimal(12,6)',
        'created_at' => 'timestamp',
        'updated_at' => 'timestamp',
    ];

    public static function assertCompatible(): void
    {
        if (! Schema::hasTable(self::TABLE)) {
            self::reject('table does not exist');
        }

        $missing = array_diff(array_keys(self::TYPES), Schema::getColumnListing(self::TABLE));

        if ($missing !== []) {
            self::reject('missing columns: '.implode(', ', $missing));
        }

        $driver = DB::getDriverName();

        if ($driver === 'mysql') {
            self::verifyMySql();
        } elseif ($driver === 'sqlite') {
            self::verifySqlite();
        } else {
            self::reject('unsupported schema validation driver: '.$driver);
        }
    }

    private static function verifyMySql(): void
    {
        $columns = DB::select(
            'SELECT COLUMN_NAME AS column_name, COLUMN_TYPE AS column_type, '.
            'IS_NULLABLE AS is_nullable, EXTRA AS extra '.
            'FROM information_schema.COLUMNS '.
            'WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ?',
            [self::TABLE]
        );

        $seen = [];
        foreach ($columns as $column) {
            $seen[$column->column_name] = $column;
        }

        foreach (self::TYPES as $name => $type) {
            $column = $seen[$name] ?? null;
            if (! $column || strtolower($column->column_type) !== $type) {
                self::reject($name.' type is '.
                    ($column ? $column->column_type : 'missing').' (expected '.$type.')');
            }

            $nullable = ! in_array($name, ['id', 'year'], true);
            if (($column->is_nullable === 'YES') !== $nullable) {
                self::reject($name.' nullability differs from the migration');
            }

            if ($name === 'id' && strpos(strtolower($column->extra), 'auto_increment') === false) {
                self::reject('id is not AUTO_INCREMENT');
            }
        }

        $indexes = DB::select(
            'SELECT INDEX_NAME AS index_name, COLUMN_NAME AS column_name, '.
            'NON_UNIQUE AS non_unique, SEQ_IN_INDEX AS seq '.
            'FROM information_schema.STATISTICS '.
            'WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ? '.
            'ORDER BY INDEX_NAME, SEQ_IN_INDEX',
            [self::TABLE]
        );
        $unique = [];
        foreach ($indexes as $index) {
            if ((int) $index->non_unique === 0) {
                $unique[$index->index_name][] = $index->column_name;
            }
        }

        if (($unique['PRIMARY'] ?? null) !== ['id']) {
            self::reject('id PRIMARY KEY is missing or incompatible');
        }

        if (! in_array(['year'], array_values($unique), true)) {
            self::reject('year requires a single-column UNIQUE index');
        }
    }

    private static function verifySqlite(): void
    {
        // PHPUnit runs with SQLite. Test both existing-table adoption and
        // fail-closed handling of a partial table without MySQL metadata.
        $columns = DB::select("PRAGMA table_info('emission_trends')");
        $seen = [];
        foreach ($columns as $column) {
            $seen[$column->name] = $column;
        }
        if ((int) ($seen['id']->pk ?? 0) !== 1) {
            self::reject('id PRIMARY KEY is missing');
        }

        if ((int) ($seen['year']->notnull ?? 0) !== 1
            || stripos((string) ($seen['year']->type ?? ''), 'int') === false) {
            self::reject('year must be a non-null integer');
        }

        foreach (self::TYPES as $name => $type) {
            if (in_array($name, ['id', 'year'], true)) {
                continue;
            }
            if ((int) ($seen[$name]->notnull ?? 1) !== 0) {
                self::reject($name.' should be nullable');
            }
        }

        $hasUniqueYear = false;
        foreach (DB::select("PRAGMA index_list('emission_trends')") as $index) {
            if ((int) $index->unique !== 1) {
                continue;
            }
            // SQLite index names come from the database, not user input.
            $escaped = str_replace("'", "''", $index->name);
            $parts = DB::select("PRAGMA index_info('".$escaped."')");
            if (count($parts) === 1 && $parts[0]->name === 'year') {
                $hasUniqueYear = true;
                break;
            }
        }
        if (! $hasUniqueYear) {
            self::reject('year requires a single-column UNIQUE index');
        }
    }

    private static function reject(string $reason): void
    {
        throw new RuntimeException(
            'Cannot reconcile the existing emission_trends table with migration '.
            '2026_01_30_164035_create_emission_trends_table: '.$reason.'. '.
            'No schema or data was changed. Back up the database, inspect SHOW CREATE TABLE emission_trends, '.
            'and repair schema differences explicitly before retrying migrate.'
        );
    }
}
